        io.stdout(`${task.taskId}: ${task.size} (confidence ${task.confidence.toFixed(2)}) -> ${route}`);
        if (task.reservationNanos !== undefined) io.stdout(`  Parallel reservation: ${formatUsd(task.reservationNanos)}`);
